const toast=(s,type='success')=>{const t=$('#toast');clearTimeout(toastTimer);t.className='micro-toast '+type;t.innerHTML=`<div class="toast-content"><span class="micro-symbol">${icon(type==='success'?'check':type==='error'?'close':'bell')}</span><div><strong>${{success:'Done',error:'Something went wrong',warning:'Attention',info:'Workspace update'}[type]||'Workspace update'}</strong><p>${esc(s)}</p></div><button class="iconbtn" aria-label="Dismiss notification">${icon('close')}</button></div><div class="toast-progress"></div>`;t.style.display='block';t.querySelector('button').onclick=()=>{clearTimeout(toastTimer);t.style.display='none'};toastTimer=setTimeout(()=>t.style.display='none',4500)};
const bytes=n=>n>1048576?(n/1048576).toFixed(1)+' MB':n>1024?(n/1024).toFixed(1)+' KB':n+' B';
