async function api(action,data=null){const done=beginFeedback(({save:'Saving',settings:'Saving settings',share:'Creating share link',temp_create:'Creating page',temp_add:'Adding content',game_profile:'Saving preferences',game_cheer:'Sending cheer',password:'Updating password',mark_read:'Updating notifications'})[action]||'Working',action==='coding_tick');try{return await sessionClient.request(action,data)}finally{done()}}
async function get(action,params={}){const done=beginFeedback('Loading');try{return await sessionClient.get(action,params)}finally{done()}}
function routeInfo(){let [r,q]=location.hash.slice(1).split('?');return [r||'overview',Object.fromEntries(new URLSearchParams(q||''))]}
function go(r){location.hash=r}
const download=id=>`download.php?id=${Number(id)}`;
let flyoutAnchor=null;
function closeFlyout(){const f=$('#micro-flyout');if(f){f.remove();flyoutAnchor?.setAttribute('aria-expanded','false');flyoutAnchor?.focus();flyoutAnchor=null}}
function flyout(anchor,body,bind,width=300){closeFlyout();flyoutAnchor=anchor;anchor.setAttribute('aria-expanded','true');const f=document.createElement('section');f.id='micro-flyout';f.className='micro-flyout';f.setAttribute('aria-label','Workspace menu');f.innerHTML=body;document.body.append(f);const r=anchor.getBoundingClientRect();f.style.width=Math.min(width,innerWidth-24)+'px';f.style.left=Math.max(12,Math.min(r.right-f.offsetWidth,innerWidth-f.offsetWidth-12))+'px';f.style.top=Math.min(r.bottom+10,innerHeight-100)+'px';f.style.maxHeight=Math.max(100,innerHeight-r.bottom-24)+'px';bind?.(f);f.querySelector('button,a')?.focus()}
document.addEventListener('pointerdown',e=>{if($('#micro-flyout')&&!$('#micro-flyout').contains(e.target)&&!flyoutAnchor?.contains(e.target))closeFlyout()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeFlyout();if(e.key==='Tab'&&$('#micro-flyout')){const xs=[...$('#micro-flyout').querySelectorAll('button:not(:disabled),a,input')];if(e.shiftKey&&document.activeElement===xs[0]){e.preventDefault();xs.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===xs.at(-1)){e.preventDefault();xs[0]?.focus()}}});window.addEventListener('resize',closeFlyout);
function modal(title,body,callback){closeFlyout();dialog.className='workspace-dialog'+(/Trash|Delete/i.test(title)?' destructive-dialog':'');dialog.setAttribute('aria-labelledby','dialog-title');dialog.innerHTML=`<header class="dialog-header"><div class="dialog-emblem">${icon(/Trash|Delete/i.test(title)?'trash':/Upload|file/i.test(title)?'upload':/Share/i.test(title)?'share':'grid')}</div><h2 id="dialog-title">${esc(title)}</h2><button type="button" class="iconbtn" data-close aria-label="Close">${icon('close')}</button></header><div class="dialog-body">${body}</div>`;const form=dialog.querySelector('form');if(form){const submit=form.querySelector(':scope > button.btn:last-child');if(submit){const actions=document.createElement('div');actions.className='dialog-actions';submit.before(actions);actions.innerHTML='<button type="button" class="btn" data-cancel>Cancel</button>';actions.append(submit);actions.querySelector('[data-cancel]').onclick=()=>dialog.close()}}const confirmActions=dialog.querySelector('.form-actions');if(confirmActions&&!confirmActions.querySelector('[data-cancel]')){const cancel=document.createElement('button');cancel.type='button';cancel.className='btn';cancel.textContent='Cancel';cancel.onclick=()=>dialog.close();confirmActions.prepend(cancel)}if(!dialog.open)dialog.showModal();dialog.querySelector('[data-close]').onclick=()=>dialog.close();callback?.(dialog)}
dialog.addEventListener('cancel',e=>{if(dialog.dataset.uploading)e.preventDefault()});
dialog.addEventListener('click',e=>{if(e.target===dialog&&!dialog.dataset.uploading){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function empty(title,text,action=''){return `<div class="empty"><div class="tileicon">${icon('folder')}</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`}
function brand(){return `<div class="brand"><div class="brand-logo">${icon('code')}</div><div><b>BOU CSE Notes</b><small>Student Workspace</small></div></div>`}
function navLinks(){return nav.map(([r,l,i])=>`<a href="#${r}" class="${current===r?'active':''}" ${current===r?'aria-current="page"':''}>${icon(i)}<span>${l}</span></a>`).join('')}
function newMenu(){flyout($('#new-menu'),`<div class="flyout-heading">QUICK CREATE</div><div class="micro-menu">${[['code','New Code','C, Java, Python or more','code'],['note','New Note','Markdown study notes','note'],['file','Upload File','Documents and resources','upload'],['project','New Project','Group your workspace','folder'],['folder','New Folder','Organize saved items','folder'],['course','Add Course','Track your study progress','code'],['goal','Lab Goal','Plan your next session','check'],['drop','Temporary Share','Files, text & code with expiry','share']].map(([k,t,d,i])=>`<button data-new="${k}"><span class="micro-symbol">${icon(i)}</span><span><strong>${t}</strong><small>${d}</small></span>${icon('plus')}</button>`).join('')}</div>`,d=>d.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>{closeFlyout();create(b.dataset.new)}))}
async function create(kind){if(kind==='drop'){go('drop');return}if(kind==='code'||kind==='note')go('edit?kind='+kind);else if(kind==='course'||kind==='goal')studyDialog(kind);else if(kind==='file')await uploadDialog();else await organizeDialog(kind)}
function heading(title,text,button=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(text)}</p></div>${button}</div>`}
function card(x,readOnly=false){if(x.kind==='file')return fileCard(x,readOnly);return `<article class="card itemcard"><div class="row between"><span class="badge">${icon(x.kind==='project'||x.kind==='folder'?'folder':x.kind==='note'?'note':x.kind==='file'?'file':'code')}${esc(x.kind==='code'?x.language:x.kind)}</span>${readOnly?'':`<button class="iconbtn" data-act="favorite" data-id="${x.id}" aria-label="${x.favorite?'Remove from':'Add to'} favorites" style="color:${x.favorite?'#ce8f17':''}">${icon('star')}</button>`}</div><h3 class="item-title mt-4" data-open="${x.id}" data-kind="${x.kind}" tabindex="0" role="button">${esc(x.title)}</h3><p class="meta">${esc(x.subject||x.description?.slice(0,80)||'Personal workspace')} · ${date(x.updated_at)}</p>${x.kind==='code'?`<div class="codepeek">${esc(x.language)} / ${esc(x.title)}\n${esc(x.description||'Saved privately in your Code Vault.')}\n// Open to continue editing</div>`:''}${x.kind==='file'?`${galleryMedia(x)}<p class="meta mt-3">${esc(x.mime)} · ${bytes(x.size_bytes)}</p>`:''}${x.tags?.length?`<div class="tags">${x.tags.slice(0,5).map(t=>`<button class="tag" data-tag="${esc(t)}">${esc(t)}</button>`).join('')}</div>`:''}<div class="item-actions"><button class="btn small soft" data-open="${x.id}" data-kind="${x.kind}">${icon(x.kind==='file'?'eye':'edit')}${x.kind==='file'?'View':'Open'}</button>${['code','note','file'].includes(x.kind)?`<a class="iconbtn" href="${download(x.id)}" aria-label="Download ${esc(x.title)}">${icon('download')}</a><button class="iconbtn" data-act="share" data-id="${x.id}" aria-label="Share">${icon('share')}</button>`:''}${['code','note'].includes(x.kind)?`<button class="iconbtn" data-act="duplicate" data-id="${x.id}" aria-label="Duplicate">${icon('copy')}</button>`:''}<button class="iconbtn" data-act="trash" data-id="${x.id}" data-kind="${x.kind}" aria-label="Move to Trash">${icon('trash')}</button></div></article>`}
function bindItems(root=$('#main')){root.querySelectorAll('[data-open]').forEach(b=>{b.onclick=()=>openItem(b.dataset.kind,b.dataset.open);b.onkeydown=e=>{if(e.key==='Enter')b.click()}});root.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>go('search?q='+encodeURIComponent(b.dataset.tag)));root.querySelectorAll('[data-act]').forEach(b=>b.onclick=async()=>{try{let a=b.dataset.act,id=+b.dataset.id;if(a==='share'){await shareDialog(id);return}if(a==='trash'){modal('Move to Trash?',`<p class="muted mt-4">${['project','folder'].includes(b.dataset.kind)?'Contained items will stay in your workspace and be moved out of this container.':'You can restore this item later. Its existing share links will be revoked.'}</p><div class="form-actions mt-5"><button class="btn" data-cancel>Cancel</button><button class="btn danger" data-confirm>${['project','folder'].includes(b.dataset.kind)?'Keep contents & trash':'Move to Trash'}</button></div>`,d=>{d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('[data-confirm]').onclick=async()=>{try{await api('trash',{id,contents:'keep'});d.close();toast('Moved to Trash');await render()}catch(e){toast(e.message,'error')}}});return}await api(a,{id});toast(a==='duplicate'?'Copy created':'Favorites updated');await render()}catch(e){toast(e.message,'error')}})}
async function openItem(kind,id){if(kind==='course')go('course?id='+id);else if(kind==='goal')go('goals');else if(kind==='file')await previewFile(+id);else if(kind==='project'||kind==='folder')go('collection?id='+id+'&kind='+kind);else go('edit?id='+id)}
async function listing(params,seq){let isCollection=current==='collection',kind=({codes:'code',notes:'note',files:'file',projects:'project'})[current]||'',mode=['favorites','trash'].includes(current)?current:'', context=null;if(isCollection){context=await get('item',{id:params.id});kind='';params[context.kind==='project'?'project_id':'folder_id']=context.id}const q=params.q||'', page=+params.page||1;let d=await get('list',{kind,mode,...params,q,page});if(seq!==routeSeq)return;const title=isCollection?context.title:({codes:'My Codes',notes:'Notes',files:'Files',projects:'Projects',favorites:'Favorites',trash:'Trash',search:'Search results'})[current];let button=kind?`<button class="btn primary" id="list-new">${icon('plus')}${kind==='file'?'Upload File':'New '+kind[0].toUpperCase()+kind.slice(1)}</button>`:isCollection?`<button class="btn" id="collection-edit">${icon('edit')}Edit ${context.kind}</button>`:'';
$('#main').innerHTML=heading(title,current==='trash'?'Restore deleted work or remove it permanently.':isCollection?'Keep related codes, notes and files together.':`${d.total} ${d.total===1?'item':'items'} in your workspace`,button)+`${isCollection?'<div class="row mb-5"><button class="btn" data-kind="code">New Code</button><button class="btn" data-kind="note">New Note</button><button class="btn" data-kind="file">Upload File</button><button class="btn" data-kind="folder">New Folder</button></div>':''}<form id="filters" class="filterbar"><input class="input" name="q" placeholder="Search ${kind||'all items'}…" value="${esc(q)}" aria-label="Search items">${kind==='code'?`<select class="input" name="language" aria-label="Filter language"><option value="">All languages</option>${languages.map(l=>`<option ${params.language===l?'selected':''}>${esc(l)}</option>`).join('')}</select>`:''}${kind==='file'?`<select class="input" name="file_type" aria-label="Filter file type">${[['','All file types'],['images','Images'],['videos','Videos'],['audio','Audio'],['pdf','PDF'],['documents','Documents'],['text','Text & CSV']].map(([v,t])=>`<option value="${v}" ${params.file_type===v?'selected':''}>${t}</option>`).join('')}</select>`:''}<select class="input" name="sort" aria-label="Sort"><option value="recent">Recently updated</option><option value="title" ${params.sort==='title'?'selected':''}>Title A–Z</option><option value="title_desc" ${params.sort==='title_desc'?'selected':''}>Title Z–A</option>${kind==='file'?`<option value="largest" ${params.sort==='largest'?'selected':''}>Largest first</option><option value="smallest" ${params.sort==='smallest'?'selected':''}>Smallest first</option><option value="type" ${params.sort==='type'?'selected':''}>File type</option>`:''}<option value="oldest" ${params.sort==='oldest'?'selected':''}>Oldest first</option></select><button class="btn">${icon('search')}Search</button></form>${mode==='trash'?'<div class="notice mb-5">'+icon('trash')+'Files in Trash still use storage. Automatic cleanup runs only when the scheduled maintenance command is configured.</div>':''}${d.items.length?`<div class="grid3">${d.items.map(x=>mode==='trash'?`<article class="card"><div class="row"><div class="tileicon">${icon(x.kind)}</div><div><h3>${esc(x.title)}</h3><p class="meta">${esc(x.kind)} · Deleted ${date(x.deleted_at)}</p></div></div><div class="item-actions"><button class="btn small" data-trash-act="restore" data-id="${x.id}">Restore</button><button class="btn small danger" data-trash-act="purge" data-id="${x.id}">Delete forever</button></div></article>`:card(x)).join('')}</div>`:empty(q?'No matching items':'Nothing here yet',q?'Try a different title, tag or keyword.':'Your saved work will appear here.')}${d.pages>1?`<div class="pagination"><button class="btn" id="prev" ${page<=1?'disabled':''}>Previous</button><span class="meta">${page} / ${d.pages}</span><button class="btn" id="next" ${page>=d.pages?'disabled':''}>Next</button></div>`:''}`;
$('#filters').querySelectorAll('select').forEach(el=>el.onchange=()=>$('#filters').requestSubmit());$('#filters').onsubmit=e=>{e.preventDefault();go(current+'?'+new URLSearchParams({...params,...Object.fromEntries(new FormData(e.target)),page:1}))};if($('#list-new'))$('#list-new').onclick=()=>create(kind);if($('#collection-edit'))$('#collection-edit').onclick=()=>organizeDialog(context.kind,context);
$('#main').querySelectorAll('[data-kind]').forEach(b=>{if(!b.dataset.open && !b.dataset.act)b.onclick=()=>{window.collectionContext=context;create(b.dataset.kind)}});
for(let [id,n] of [['prev',page-1],['next',page+1]])if($('#'+id))$('#'+id).onclick=()=>go(current+'?'+new URLSearchParams({...params,page:n}));bindItems();bindFileMenus($('#main'));$('#main').querySelectorAll('[data-trash-act]').forEach(b=>b.onclick=()=>{let act=b.dataset.trashAct;if(act==='purge')modal('Delete permanently?',`<p class="muted mt-4">This removes the item and its uploaded file bytes. It cannot be restored.</p><div class="form-actions mt-5"><button class="btn danger" data-confirm>Delete forever</button></div>`,d=>d.querySelector('[data-confirm]').onclick=async()=>{try{await api(act,{id:+b.dataset.id});d.close();toast('Permanently deleted');await render()}catch(e){toast(e.message,'error')}});else api(act,{id:+b.dataset.id}).then(()=>{toast('Item restored');render()}).catch(e=>toast(e.message,'error'))});}
let editorPromise;function loadEditor(){if(window.CodeMirror)return Promise.resolve();if(!editorPromise)editorPromise=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href=boot?.editorCss||'assets/editor.css?v=speed-1';document.head.append(css);const script=document.createElement('script');script.src=boot?.editorJs||'assets/editor.js?v=speed-1';script.onload=()=>window.CodeMirror?resolve():reject(Error('Code editor unavailable. Reload and retry.'));script.onerror=()=>reject(Error('Code editor failed to load. Retry when connected.'));document.head.append(script)}).catch(e=>{editorPromise=null;throw e});return editorPromise;}
async function getOptions(){options=await get('options');return options}
function selectOptions(xs,id,blank='None'){return `<option value="">${blank}</option>`+xs.map(x=>`<option value="${x.id}" ${+id===+x.id?'selected':''}>${esc(x.title)}</option>`).join('')}
function relationFields(x={}){return `<label class="field">Project<select class="input" name="project_id" id="project-select">${selectOptions(options.projects,x.project_id)}</select></label><label class="field">Folder<select class="input" name="folder_id" id="folder-select">${selectOptions(options.folders.filter(f=>+f.project_id===+(x.project_id||0)),x.folder_id)}</select></label>`}
function bindRelation(root){let p=root.querySelector('#project-select'),f=root.querySelector('#folder-select');if(p&&f)p.onchange=()=>{f.innerHTML=selectOptions(options.folders.filter(x=>+x.project_id===+(p.value||0)),null);p.dispatchEvent(new Event('input',{bubbles:true}));};}
async function organizeDialog(kind,x={}){await getOptions();let c=window.collectionContext;window.collectionContext=null;if(!x.id&&c){x.project_id=c.kind==='project'?c.id:c.project_id;x.folder_id=c.kind==='folder'?c.id:null}modal(x.id?'Edit '+kind:'New '+kind,`<form id="organize-form"><label class="field">Name<input class="input" name="title" required maxlength="255" value="${esc(x.title)}"></label><label class="field">Description<textarea class="input" name="description" maxlength="20000">${esc(x.description)}</textarea></label>${kind==='folder'?relationFields(x):''}<div class="error hidden" id="form-error"></div><button class="btn primary">${x.id?'Save changes':'Create '+kind}</button></form>`,d=>{bindRelation(d);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('save',{...Object.fromEntries(new FormData(e.target)),id:x.id,kind});d.close();toast(kind+' saved');await render()}catch(e){let el=d.querySelector('#form-error');el.textContent=e.message;el.classList.remove('hidden')}}})}
function dropzone(id='upload-files',limit='Your workspace upload limit applies'){return `<div class="dropzone" role="group" aria-label="File upload">${icon('upload')}<strong>Select files to upload</strong><span>Choose from your phone or computer, or drag files here.</span><small>${esc(limit)}</small><label class="file-picker-label" for="${id}">Choose files</label><input class="input" id="${id}" type="file" name="file" multiple accept="image/*,video/*,audio/*,.pdf,.txt,.md,.csv,.docx,.odt"><div class="drop-selection" aria-live="polite"></div></div>`}
function bindDropzone(root,onFiles){const zone=root.querySelector('.dropzone'),input=zone.querySelector('input');let files=[];const set=xs=>{files=Array.from(xs||[]);zone.querySelector('.drop-selection').textContent=files.map(f=>f.name+' ('+bytes(f.size)+')').join(' · ');onFiles?.(files)};input.onchange=()=>set(input.files);zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragging')};zone.ondragleave=()=>zone.classList.remove('dragging');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragging');set(e.dataTransfer.files)};return ()=>files}
function galleryMedia(x,url=download(x.id)+'&inline=1',full=false){const ext=(x.original_name||x.title||'').split('.').pop().toLowerCase(),attrs=`data-full="${full?'true':''}"`;if(x.mime?.startsWith('image/'))return `<div class="gallery-media"><img src="${esc(url)}" alt="${esc(x.title)}" loading="lazy"></div>`;if(x.mime?.startsWith('video/'))return `<div class="gallery-media"><video src="${esc(url)}" controls playsinline preload="metadata" aria-label="${esc(x.title)}"></video></div>`;if(x.mime?.startsWith('audio/')||x.mime==='application/ogg')return `<div class="gallery-media audio-preview">${icon('file')}<strong>Audio recording</strong><audio src="${esc(url)}" controls preload="metadata" aria-label="${esc(x.title)}"></audio></div>`;if(x.mime==='application/pdf'||['docx','odt','txt','md','csv'].includes(ext))return `<div class="gallery-media file-preview-content ${x.mime==='application/pdf'?'pdf-preview':'text-document-preview'}" data-preview-type="${x.mime==='application/pdf'?'pdf':'text'}" data-preview-url="${esc(url)}" ${attrs}><p class="preview-loading" role="status"><i class="feedback-spinner"></i>Loading preview…</p></div>`;return `<div class="gallery-media preview-fallback">${icon('file')}Preview unavailable for this format</div>`}
function fileCard(x,readOnly=false){return `<article class="file-tile" data-file-tile="${x.id}" tabindex="0" aria-label="${esc(x.title)}"><div class="file-tile-preview">${galleryMedia(x)}${readOnly?'':`<div class="file-hover-actions"><button class="iconbtn" data-open="${x.id}" data-kind="file" aria-label="Preview ${esc(x.title)}">${icon('eye')}</button><a class="iconbtn" href="${download(x.id)}" aria-label="Download ${esc(x.title)}">${icon('download')}</a><button class="iconbtn" data-act="share" data-id="${x.id}" aria-label="Share ${esc(x.title)}">${icon('share')}</button><button class="iconbtn" data-act="trash" data-kind="file" data-id="${x.id}" aria-label="Move ${esc(x.title)} to Trash">${icon('trash')}</button></div>`}</div><footer><div><h3 class="item-title" data-open="${x.id}" data-kind="file" tabindex="0" role="button">${esc(x.title)}</h3><p class="meta">${esc((x.original_name||x.title).split('.').pop().toUpperCase())} · ${bytes(x.size_bytes)} · ${date(x.updated_at)}</p></div>${readOnly?'':`<button class="iconbtn file-menu-trigger" data-file-menu="${x.id}" aria-label="Actions for ${esc(x.title)}">${icon('menu')}</button>`}</footer></article>`}
function bindFileMenus(root){root.querySelectorAll('[data-file-tile]').forEach(tile=>{const show=e=>{e?.preventDefault();const id=+tile.dataset.fileTile;const anchor=tile.querySelector('[data-file-menu]');flyout(anchor,`<nav class="micro-menu"><button data-open="${id}" data-kind="file">${icon('eye')}Preview</button><a href="${download(id)}">${icon('download')}Download</a><button data-file-edit="${id}">${icon('edit')}Rename / Move</button><button data-act="favorite" data-id="${id}">${icon('star')}Toggle favorite</button><button data-act="share" data-id="${id}">${icon('share')}Share</button><button data-act="trash" data-kind="file" data-id="${id}">${icon('trash')}Move to Trash</button></nav>`,f=>{bindItems(f);f.querySelector('[data-file-edit]').onclick=async()=>{closeFlyout();await fileEdit(await get('item',{id}))};f.querySelectorAll('button,a').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.act!=='trash')closeFlyout()}))},240);if(e?.type==='contextmenu'){const f=$('#micro-flyout');f.style.left=Math.max(12,Math.min(e.clientX,innerWidth-f.offsetWidth-12))+'px';f.style.top=Math.max(12,Math.min(e.clientY,innerHeight-f.offsetHeight-12))+'px';}};tile.oncontextmenu=show;tile.querySelector('[data-file-menu]')?.addEventListener('click',show);tile.onkeydown=e=>{if(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10')show(e)};})}

async function uploadDialog(){const [,policy]=await Promise.all([getOptions(),get('upload_policy')]);let c=window.collectionContext;window.collectionContext=null;let x={project_id:c?.kind==='project'?c.id:c?.project_id,folder_id:c?.kind==='folder'?c.id:null};modal('Upload files',`<form id="upload-form">${dropzone('upload-files','Maximum per file: '+bytes(policy.max_file_bytes))}<details class="upload-organize"><summary>Organize files (optional)</summary>${relationFields(x)}</details>${progressMarkup()}<div id="upload-status" class="meta" role="status"></div><button class="btn primary">${icon('upload')}Upload Files</button></form>`,d=>{bindRelation(d);let pending=[];bindDropzone(d,files=>pending=files);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.target,btn=form.querySelector('button.primary'),feedback=form.querySelector('.upload-feedback');if(!pending.length){d.querySelector('#upload-status').textContent='Drop files or choose files first.';return}if(pending.some(f=>!f.size||f.size>policy.max_file_bytes)){d.querySelector('#upload-status').textContent='Choose non-empty files no larger than '+bytes(policy.max_file_bytes)+' each.';return}const batch=[...pending],total=batch.reduce((n,f)=>n+f.size,0);let completedBytes=0,done=0;updateProgress(feedback,0,'Preparing upload…',`${batch.length} files queued`);form.setAttribute('aria-busy','true');d.dataset.uploading='true';form.querySelectorAll('button,input,select').forEach(el=>el.disabled=true);d.querySelector('[data-close]').disabled=true;btn.classList.add('request-busy');d.querySelector('#upload-status').textContent='Keep this page open until your upload completes.';try{for(const file of batch){const f=new FormData();f.set('file',file);f.set('project_id',form.elements.project_id?.value||'');f.set('folder_id',form.elements.folder_id?.value||'');await sessionClient.upload('upload',f,(ratio,state)=>updateProgress(feedback,ratio===null?null:Math.min(99,100*(completedBytes+ratio*file.size)/total),state==='processing'?'Processing file…':`Uploading ${done+1} of ${batch.length}`,file.name+' · '+bytes(file.size)));completedBytes+=file.size;done++;pending=pending.filter(x=>x!==file);const line=document.createElement('p');line.className='upload-file-done';line.textContent='✓ '+file.name;feedback.querySelector('.upload-file-statuses').append(line)}updateProgress(feedback,100,'Upload complete',`${done} ${done===1?'file':'files'} saved to your gallery`,'complete');d.querySelector('#upload-status').textContent='Your files are ready.';toast('Files uploaded');d.dataset.uploading='';d.close();await render()}catch(e){updateProgress(feedback,100*completedBytes/total,'Upload needs attention',`${done} saved · ${pending.length} remaining. ${e.message}`,'error');btn.innerHTML=icon('upload')+'Retry remaining files';d.querySelector('#upload-status').textContent='Successfully uploaded files will not be sent again.';toast(e.message,'error')}finally{d.dataset.uploading='';form.removeAttribute('aria-busy');form.querySelectorAll('button,input,select').forEach(el=>el.disabled=false);d.querySelector('[data-close]').disabled=false;btn.classList.remove('request-busy')}}})}

async function previewFile(id){let x=await get('item',{id});modal(x.title,`<p class="meta">${esc(x.mime)} · ${bytes(x.size_bytes)}</p><div id="file-content" class="full-file-preview mt-4">${galleryMedia(x,download(id)+'&inline=1',true)}</div><div class="row mt-5"><a class="btn primary" href="${download(id)}">${icon('download')}Download</a><button class="btn" id="rename-file">Rename / Move</button></div>`,d=>{d.querySelector('#rename-file').onclick=()=>{d.close();fileEdit(x)}})}
async function fileEdit(x){await getOptions();modal('Edit file details',`<form><label class="field">Display name<input name="title" class="input" required maxlength="255" value="${esc(x.title)}"></label>${relationFields(x)}<button class="btn primary">Save changes</button></form>`,d=>{bindRelation(d);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('save',{...x,...Object.fromEntries(new FormData(e.target))});d.close();toast('File details updated');render()}catch(e){toast(e.message,'error')}}})}
function markdown(text){ // Escaping first keeps user Markdown inert; links allow only https/http.
let lines=esc(text).split('\n'),out=[],code=false,list=false;for(let l of lines){if(l.startsWith('```')){if(list){out.push('</ul>');list=false}out.push(code?'</code></pre>':'<pre><code>');code=!code;continue}if(code){out.push(l+'\n');continue}l=l.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*(.+?)\*/g,'<em>$1</em>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" rel="noopener noreferrer" target="_blank">$1</a>');let h=l.match(/^(#{1,3}) (.*)$/);if(l.startsWith('- ')){if(!list){out.push('<ul>');list=true}out.push('<li>'+l.slice(2)+'</li>')}else{if(list){out.push('</ul>');list=false}out.push(h?`<h${h[1].length}>${h[2]}</h${h[1].length}>`:`<p>${l||'<br>'}</p>`)}}if(list)out.push('</ul>');if(code)out.push('</code></pre>');return out.join('')}
function getEditorValue(){return editor?editor.getValue():$('#content')?.value||''}
function modeFor(l){return {C:'text/x-csrc','C++':'text/x-c++src',Java:'text/x-java',Python:'python',JavaScript:'javascript',PHP:'application/x-httpd-php',SQL:'text/x-sql',HTML:'htmlmixed',CSS:'css','8086 / Assembly':'text/plain'}[l]||'text/plain'}
async function editPage(params,seq){const [opts,record]=await Promise.all([getOptions(),params.id?get('item',{id:params.id}):Promise.resolve(null)]);let x=record||{kind:params.kind||'code',title:'',content:'',language:me.preferences?.default_language||'C',tags:[],attachments:[],project_id:null,folder_id:null,pinned:0};let c=window.collectionContext;window.collectionContext=null;if(!x.id&&c){x.project_id=c.kind==='project'?c.id:c.project_id;x.folder_id=c.kind==='folder'?c.id:null}if(x.kind==='code')await loadEditor();if(seq!==routeSeq)return;currentItem=x;dirty=false;
$('#main').innerHTML=heading(x.id?'Edit '+(x.kind==='code'?'code':'note'):'New '+(x.kind==='code'?'code':'note'),x.kind==='code'?'Write, organize and save. Code execution is disabled.':'Write in Markdown. Preview headings, lists and code blocks.',`<span class="saving" id="save-status">${x.id?'All changes saved':'Not saved yet'}</span><button class="btn primary" id="save-btn">Save</button>`)+`<form id="editor-form"><div class="editor-grid"><div class="stack"><label class="field">Title<input class="input" name="title" required maxlength="255" value="${esc(x.title)}" placeholder="e.g. Binary Search — DS Lab"></label><div class="editor-meta">${x.kind==='code'?`<label class="field">Language<select name="language" class="input" id="language-select">${languages.map(l=>`<option ${x.language===l?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`:''}<label class="field">Subject / Course<input class="input" name="subject" maxlength="120" value="${esc(x.subject)}" placeholder="Data Structures"></label></div><div class="editor-wrap"><div class="editor-toolbar"><span class="meta">${x.kind==='code'?'Code editor':'Markdown note'}</span><div class="row"><button type="button" class="btn small" id="copy-code">${icon('copy')}Copy</button><button type="button" class="btn small" id="fullscreen">${x.kind==='code'?'Full screen':'Preview'}</button></div></div><textarea id="content" name="content" class="input ${x.kind==='note'?'note-editor':''}" aria-label="${x.kind==='code'?'Code':'Note content'}" spellcheck="false">${esc(x.content)}</textarea><div id="note-preview" class="preview p-5 hidden"></div></div><label class="field">Description<textarea class="input" name="description" maxlength="20000" placeholder="What does this solve?">${esc(x.description)}</textarea></label></div><aside class="stack"><section class="card stack"><h3>Organization</h3>${relationFields(x)}<label class="field">Tags<input class="input" name="tags" id="tags-input" list="tag-options" value="${esc(x.tags.join(', '))}" placeholder="array, lab, exam"><small>Separate tags with commas.</small><datalist id="tag-options">${[...new Set(options.tags.flatMap(t=>{try{return JSON.parse(t.tags||'[]')}catch{return[]}}))].map(t=>`<option value="${esc(t)}">`).join('')}</datalist></label>${x.kind==='note'?`<label class="check"><input name="pinned" type="checkbox" ${x.pinned?'checked':''}> Pin this note</label>`:''}<div class="badge">${icon('lock')}Private by default</div></section><section class="card"><div class="section-head"><h3>Attachments</h3><button type="button" class="iconbtn" id="attach-file" aria-label="Attach a file">${icon('plus')}</button></div><div id="attachments"></div><p class="meta mt-2">Attachments remain private when you share this item.</p></section>${x.id?`<section class="card stack"><h3>Item actions</h3><a class="btn" href="${download(x.id)}">${icon('download')}Download</a><button type="button" class="btn" id="editor-share">${icon('share')}Share read-only</button>${x.kind==='code'?'<button type="button" class="btn" id="versions-btn">'+icon('clock')+'Version history</button>':''}</section>`:''}</aside></div></form>`;
let textarea=$('#content');if(x.kind==='code'&&window.CodeMirror){editor=CodeMirror.fromTextArea(textarea,{lineNumbers:true,mode:modeFor(x.language),indentUnit:4,tabSize:4,lineWrapping:false,matchBrackets:true,extraKeys:{Tab:cm=>cm.replaceSelection('    '),F11:cm=>cm.setOption('fullScreen',!cm.getOption('fullScreen')),Esc:cm=>cm.setOption('fullScreen',false)}});editor.on('change',markDirty);$('#language-select').addEventListener('change',e=>editor.setOption('mode',modeFor(e.target.value)))}
$('#editor-form').onsubmit=e=>{e.preventDefault();saveCurrent()};$('#editor-form').addEventListener('input',markDirty);bindRelation($('#editor-form'));$('#save-btn').onclick=()=>saveCurrent(true);$('#copy-code').onclick=async()=>{try{await navigator.clipboard.writeText(getEditorValue());toast('Copied to clipboard')}catch{toast('Select and copy the content using your keyboard.')}};$('#fullscreen').onclick=()=>{if(editor)editor.setOption('fullScreen',!editor.getOption('fullScreen'));else{let p=$('#note-preview');p.innerHTML=markdown(getEditorValue());p.classList.toggle('hidden');textarea.classList.toggle('hidden')}};if($('#editor-share'))$('#editor-share').onclick=()=>shareDialog(x.id);if($('#versions-btn'))$('#versions-btn').onclick=()=>versionDialog(x.id);renderAttachments();$('#attach-file').onclick=attachmentDialog;}
function saveFeedback(text,state){const el=$('#save-status');if(el){el.textContent=text;el.dataset.state=state;el.setAttribute('role','status')}}
function markDirty(){dirty=true;if($('#save-status'))saveFeedback('Unsaved changes','pending');clearTimeout(timer);timer=setTimeout(()=>saveCurrent(false),3000)}
async function saveCurrent(manual=false){if(!currentItem||current!=='edit')return;if(saving){rerun=true;return}let form=$('#editor-form');if(!form)return;let data=Object.fromEntries(new FormData(form));if(!data.title.trim()){if(manual)toast('Add a title before saving.');return}data={...data,id:currentItem.id,kind:currentItem.kind,content:getEditorValue(),tags:data.tags.split(',').map(t=>t.trim()).filter(Boolean),pinned:form.querySelector('[name=pinned]')?.checked||false,attachments:currentItem.attachments.map(f=>f.id),expected_updated_at:currentItem.updated_at,expected_revision:currentItem.revision};saving=true;dirty=false;saveFeedback('Saving…','saving');try{let saved=await api('save',data),first=!currentItem.id;currentItem={...saved,attachments:currentItem.attachments};if(first){history.replaceState(null,'','#edit?id='+saved.id);lastRoute=location.hash;$('#main h1').textContent='Edit '+(saved.kind==='code'?'code':'note');let side=$('#editor-form aside');side.insertAdjacentHTML('beforeend',`<section class="card stack"><h3>Item actions</h3><a class="btn" href="${download(saved.id)}">${icon('download')}Download</a><button type="button" class="btn" id="editor-share">${icon('share')}Share read-only</button>${saved.kind==='code'?'<button type="button" class="btn" id="versions-btn">'+icon('clock')+'Version history</button>':''}</section>`);$('#editor-share').onclick=()=>shareDialog(saved.id);if($('#versions-btn'))$('#versions-btn').onclick=()=>versionDialog(saved.id)}if($('#save-status'))saveFeedback(dirty?'Unsaved changes':'All changes saved',dirty?'pending':'saved');if(manual)toast('Saved');}catch(e){dirty=true;if($('#save-status'))saveFeedback('Failed to save','error');toast(e.message+' Your edits remain in this editor.','error')}finally{saving=false;if(rerun){rerun=false;saveCurrent(false)}}}
function renderAttachments(){let el=$('#attachments');if(el)el.innerHTML=currentItem.attachments.length?currentItem.attachments.map(f=>`<div class="row between text-sm mb-2"><a href="${download(f.id)}">${esc(f.title)}</a><button type="button" class="iconbtn" data-remove="${f.id}" aria-label="Remove attachment">${icon('close')}</button></div>`).join(''):'<p class="meta">No files attached.</p>';el?.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{currentItem.attachments=currentItem.attachments.filter(f=>f.id!==+b.dataset.remove);renderAttachments();markDirty()})}
async function attachmentDialog(){let d=await get('list',{kind:'file'});modal('Attach a saved file',d.items.length?`<form>${d.items.map(f=>`<label class="check"><input type="checkbox" name="file" value="${f.id}" ${currentItem.attachments.some(x=>x.id===f.id)?'checked':''}>${esc(f.title)} <small>${bytes(f.size_bytes)}</small></label>`).join('')}<p class="meta">Showing 30 recent files. Upload more from Files.</p><button class="btn primary">Attach selected</button></form>`:empty('Upload a file first','Open Files to upload your resources.'),el=>{let f=el.querySelector('form');if(f)f.onsubmit=e=>{e.preventDefault();let ids=new FormData(f).getAll('file').map(Number);currentItem.attachments=[...currentItem.attachments.filter(x=>!d.items.some(a=>a.id===x.id)),...d.items.filter(x=>ids.includes(x.id))];renderAttachments();markDirty();el.close()}})}
async function versionDialog(id){let x=await get('item',{id});modal('Version history',x.versions.length?`<div class="stack mt-5">${x.versions.map(v=>`<button class="btn" data-version="${v.id}">${icon('clock')}${esc(v.created_at)} UTC</button>`).join('')}</div>`:empty('No older versions','Changed code is retained when a new edit is saved.'),d=>d.querySelectorAll('[data-version]').forEach(b=>b.onclick=async()=>{let v=await get('version',{id:b.dataset.version});modal('Saved version',`<pre class="tool-output mt-4">${esc(v.content)}</pre><button class="btn primary mt-4" id="restore-version">Restore this version</button>`,el=>el.querySelector('#restore-version').onclick=async()=>{try{await api('version_restore',{id:v.id});dirty=false;el.close();toast('Version restored');await render()}catch(e){toast(e.message,'error')}})}))}
async function shareDialog(id){let x=await get('item',{id});modal('Share read-only',`<p class="muted text-sm mt-4">Anyone with an unlisted link can view this item. Enter a verified account email for a private direct share. Attached files are not included.</p><form id="share-form"><label class="field">Recipient email (optional)<input type="email" name="email" class="input" placeholder="classmate@example.com"></label><label class="field">Expires after<select name="days" class="input"><option value="0">Never</option><option value="7">7 days</option><option value="30">30 days</option></select></label><button class="btn primary">Create share link</button></form><div id="share-result" class="mt-4"></div><h3 class="mt-5">Active shares</h3><div class="stack mt-3">${x.shares.length?x.shares.map(s=>`<div class="row between text-sm"><span>${esc(s.email||'Unlisted link')}<small class="block">${s.expires_at?'Expires '+date(s.expires_at):'No expiry'}</small></span><button class="btn small danger" data-revoke="${s.id}">Revoke</button></div>`).join(''):'<p class="meta">No active shares.</p>'}</div>`,d=>{d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{let r=await api('share',{id,...Object.fromEntries(new FormData(e.target))});d.querySelector('#share-result').innerHTML=`<label class="field">Copy this link now<input class="input" readonly value="${esc(r.url)}"></label><div class="row mt-3"><button class="btn small" type="button" id="copy-share-link">Copy link</button><a class="btn small" id="download-share-qr" download="share-qr.png">Download QR</a></div><canvas class="drop-qr" id="share-qr" aria-label="Share link QR code"></canvas><p class="meta mt-2">The secret link is shown once. Create a new link if you lose it.</p>`;await (await loadQR()).toCanvas(d.querySelector('#share-qr'),r.url,{width:180,margin:2,color:{dark:'#032f73',light:'#ffffff'}});d.querySelector('#download-share-qr').href=d.querySelector('#share-qr').toDataURL();d.querySelector('#copy-share-link').onclick=async()=>{try{await navigator.clipboard.writeText(r.url);toast('Share link copied')}catch{d.querySelector('#share-result input').select()}};d.querySelector('#share-result input').select()}catch(e){toast(e.message,'error')}};d.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=async()=>{try{await api('revoke',{id:+b.dataset.revoke});b.closest('div').remove();toast('Share revoked')}catch(e){toast(e.message,'error')}})})}
function approvalPage(){app.innerHTML=`<div class="auth"><div class="auth-story">${brand()}<h1>Your workspace<br>is almost ready.</h1><p>Your email is verified. An administrator will review your account.</p></div><div class="auth-panel"><div class="auth-form"><h2>${me.approval==='rejected'?'Account request declined':'Waiting for approval'}</h2><p class="muted mt-4">Requested role: ${esc(me.role)}.</p>${me.approval_note?`<div class="notice mt-4">${esc(me.approval_note)}</div>`:''}<button class="btn primary mt-5" id="approval-check">Check approval</button><button class="btn mt-5" id="approval-logout">Sign out</button></div></div></div>`;$('#approval-check').onclick=async()=>{try{const s=await get('session');me=s.user;if(!me){go('login');return}if(me.approval==='approved'){toast('Your account is approved');go('overview');await render()}else toast('Your account is still '+me.approval,'info')}catch(e){toast(e.message,'error')}};$('#approval-logout').onclick=logout;}

function memberPicker(members,selected=[],name='members'){
 const ids=new Set(selected.map(String));return `<div class="member-picker" style="max-height:260px;overflow:auto;border:1px solid #e2e8f0;padding:12px;border-radius:12px">${members.map(m=>`<label class="check"><input type="checkbox" name="${name}" value="${m.id}" ${ids.has(String(m.id))?'checked':''}>${esc(m.name)}${m.email?` <small>${esc(m.email)}</small>`:''}</label>`).join('')||'<p class="meta">No approved members available.</p>'}</div>`;
}
async function adminPage(seq,params={}){
 const page=Number(params.page)||1,d=await get('control_data',{q:params.q||'',page});if(seq!==routeSeq)return;
 const userRows=d.users.map(u=>`<tr><td>${esc(u.name)}<small class="block">${esc(u.email)}</small></td><td>${esc(u.role)}</td><td><span class="badge">${esc(u.approval)}</span><small class="block">${esc(u.status)}</small></td><td>${bytes(Number(u.used))} / ${u.effective_quota} MB<small class="block">${u.effective_upload} MB per file</small></td><td>${['admin','super_admin'].includes(u.role)?'<span class="meta">Protected</span>':`<button class="btn small" data-control-user="${u.id}">Manage</button>`}</td></tr>`).join('');
 const guestFields=[['file_mb','Per-file limit (MB)',1,100],['text_mb','Text/code limit (MB)',1,5],['page_mb','Per-page storage (MB)',1,500],['entries','Entries per page',1,100],['total_mb','Total temporary storage (MB)',1,50000],['pages_hour','Pages per IP per hour',1,100],['max_hours','Maximum expiry (hours)',1,168]];
 $('#main').innerHTML=heading('Super Admin','Approve accounts, grant teacher permissions and manage individual storage.')+`<div class="stack"><section class="card"><div class="row between"><h2>Accounts & approvals</h2><a class="btn small" href="#admin-system">Global settings, logs & share links</a></div><form class="row mt-4" id="control-search"><input class="input" name="q" aria-label="Search accounts" placeholder="Search name or email" value="${esc(params.q||'')}"><button class="btn">Search</button></form><div class="table-wrap mt-4"><table class="table"><thead><tr><th>Account</th><th>Role</th><th>Approval / status</th><th>Storage</th><th>Action</th></tr></thead><tbody>${userRows||'<tr><td colspan="5">No matching accounts.</td></tr>'}</tbody></table></div><p class="meta mt-4">${d.total} accounts · Page ${page}</p><div class="row">${page>1?`<button class="btn small" data-control-page="${page-1}">Previous</button>`:''}${page*100<d.total?`<button class="btn small" data-control-page="${page+1}">Next</button>`:''}</div></section><section class="card"><h2>Storage requests</h2><div class="stack mt-4">${d.requests.map(r=>`<article><strong>${esc(r.name)} · ${r.requested_mb} MB total quota</strong><p class="meta">${esc(r.email)}</p><p>${esc(r.reason)}</p><div class="row mt-3"><button class="btn small primary" data-review="${r.id}" data-decision="approved">Approve</button><button class="btn small danger" data-review="${r.id}" data-decision="rejected">Reject</button></div></article>`).join('')||'<p class="meta">No pending requests.</p>'}</div></section><section class="card"><h2>Anonymous sharing limits</h2><p class="meta mt-3">Hosting PHP upload limits still apply. These limits are enforced on the server.</p><form id="guest-config" class="stack mt-4"><label class="check"><input type="checkbox" name="enabled" ${d.guest.enabled?'checked':''}>Enable anonymous sharing</label><div class="grid2">${guestFields.map(([k,label,min,max])=>`<label class="field">${label}<input class="input" type="number" name="${k}" min="${min}" max="${max}" required value="${d.guest[k]}"></label>`).join('')}</div><button class="btn primary self-start">Save anonymous limits</button></form></section><section class="card"><h2>Recent permission changes</h2><div class="table-wrap mt-4"><table class="table"><thead><tr><th>Actor</th><th>Action</th><th>Target ID</th><th>Time (UTC)</th></tr></thead><tbody>${d.audit.map(a=>`<tr><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td>${a.target_id||'—'}</td><td>${esc(a.created_at)}</td></tr>`).join('')||'<tr><td colspan="4">No changes yet.</td></tr>'}</tbody></table></div></section></div>`;
 $('#control-search').onsubmit=e=>{e.preventDefault();go('admin?'+new URLSearchParams({q:new FormData(e.target).get('q'),page:1}))};
 $('#main').querySelectorAll('[data-control-page]').forEach(b=>b.onclick=()=>go('admin?'+new URLSearchParams({q:params.q||'',page:b.dataset.controlPage})));
 $('#main').querySelectorAll('[data-control-user]').forEach(b=>b.onclick=()=>{
  const u=d.users.find(u=>Number(u.id)===Number(b.dataset.controlUser));modal('Manage '+u.name,`<form id="control-user" class="stack"><div class="grid2"><label class="field">Role<select name="role" class="input">${['student','teacher'].map(v=>`<option ${v===u.role?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Approval<select name="approval" class="input">${['pending','approved','rejected'].map(v=>`<option ${v===u.approval?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Status<select name="status" class="input">${['active','suspended'].map(v=>`<option ${v===u.status?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Total quota override (MB)<input class="input" name="quota_mb" type="number" min="1" max="100000" value="${u.custom_quota??''}" placeholder="Default ${u.effective_quota}"></label><label class="field">Per-file limit override (MB)<input class="input" name="max_upload_mb" type="number" min="1" max="500" value="${u.custom_upload??''}" placeholder="Default ${u.effective_upload}"></label></div><p class="meta">Leave limits blank to follow global defaults. Lowering a quota never deletes stored files.</p><label class="check"><input type="checkbox" name="allow_publish" ${(u.allow_publish??(u.role==='teacher'?1:0))?'checked':''}>Teacher: share and notify members</label><label class="check"><input type="checkbox" name="allow_groups" ${(u.allow_groups??(u.role==='teacher'?1:0))?'checked':''}>Teacher: create and manage groups</label><label class="field">Note to account owner<textarea class="input" name="note" maxlength="1000">${esc(u.note||'')}</textarea></label><button class="btn primary">Save account permissions</button></form>`,dlg=>{dlg.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));data.id=u.id;for(const k of ['allow_publish','allow_groups'])data[k]=form.elements[k].checked?1:0;try{await api('control_user',data);dlg.close();toast('Account updated');await render()}catch(e){toast(e.message,'error')}}});
 });
 $('#main').querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{try{await api('control_request',{id:Number(b.dataset.review),status:b.dataset.decision});toast('Request '+b.dataset.decision);await render()}catch(e){toast(e.message,'error')}});
 $('#guest-config').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.enabled=e.target.elements.enabled.checked?1:0;try{await api('control_guest',data);toast('Anonymous limits updated')}catch(e){toast(e.message,'error')}};
}

async function groupsPage(seq){
 const d=await get('group_data');if(seq!==routeSeq)return;
 $('#main').innerHTML=heading('Groups','Group membership controls who receives targeted teacher updates.')+`<div class="row mb-5">${d.permissions.groups?'<button class="btn primary" id="new-group">Create group</button>':''}${d.permissions.publish?'<a class="btn" href="#teacher">Share / send notification</a>':''}</div><div class="grid2">${d.groups.map(g=>`<article class="card"><h2>${esc(g.name)}</h2><p class="meta mt-3">${g.members.length} members</p><p class="mt-3">${g.members.map(x=>esc(x.name)).join(', ')||'No members yet.'}</p>${g.can_manage?`<div class="row mt-4"><button class="btn small" data-edit-group="${g.id}">Edit members</button><button class="btn small danger" data-delete-group="${g.id}">Delete group</button></div>`:''}</article>`).join('')||empty('No groups yet','Your teacher can add you to a group.')}</div>`;
 const edit=g=>modal(g?'Edit group':'Create group',`<form id="group-form" class="stack"><label class="field">Group name<input name="name" class="input" required maxlength="120" value="${esc(g?.name||'')}"></label><h3>Select approved members</h3>${memberPicker(d.members,g?.members.map(x=>x.id)||[])}<button class="btn primary">Save group</button></form>`,dlg=>dlg.querySelector('form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);try{await api('group_save',{id:g?.id||0,name:fd.get('name'),members:fd.getAll('members')});dlg.close();toast('Group saved');await render()}catch(e){toast(e.message,'error')}});
 if(d.permissions.groups)$('#new-group').onclick=()=>edit(null);
 $('#main').querySelectorAll('[data-edit-group]').forEach(b=>b.onclick=()=>edit(d.groups.find(x=>Number(x.id)===Number(b.dataset.editGroup))));
 $('#main').querySelectorAll('[data-delete-group]').forEach(b=>b.onclick=()=>modal('Delete group?',`<p>This removes the group and its membership list. Previously delivered shares stay available until revoked.</p><button class="btn danger mt-4" data-confirm>Delete group</button>`,dlg=>dlg.querySelector('[data-confirm]').onclick=async()=>{try{await api('group_delete',{id:Number(b.dataset.deleteGroup)});dlg.close();await render()}catch(e){toast(e.message,'error')}}));
}

async function teacherPage(seq){
 const d=await get('group_data');if(seq!==routeSeq)return;if(!d.permissions.publish)throw Error('Teacher publishing permission required.');
 const managed=d.groups.filter(g=>g.can_manage||Number(g.owner_id)===Number(me.id));
 $('#main').innerHTML=heading('Teacher sharing','Share a saved resource or announcement and notify its audience.')+`<section class="card"><form id="teacher-publish" class="stack"><label class="field">Title<input class="input" name="title" required maxlength="255"></label><label class="field">Message<textarea class="input" name="message" maxlength="4000" placeholder="Add instructions or an announcement"></textarea></label><label class="field">Saved resource (optional)<select class="input" name="item_id"><option value="">Announcement only</option>${d.items.map(i=>`<option value="${i.id}">${esc(i.title)} (${esc(i.kind)})</option>`).join('')}</select><small>Upload a file or save code in your workspace first, then select it here.</small></label><label class="field">Audience<select class="input" name="audience"><option value="all">All approved members</option><option value="groups">Selected groups</option><option value="members">Selected members</option></select></label><div id="audience-groups" hidden><h3 class="mb-3">Select your groups</h3>${memberPicker(managed.map(g=>({id:g.id,name:g.name})),[],'groups')}</div><div id="audience-members" hidden><h3 class="mb-3">Select members</h3>${memberPicker(d.members)}</div><p class="meta">Group/member recipients are selected at publishing time. A member in multiple groups gets one notification. All-member shares are also visible to future approved members.</p><button class="btn primary self-start">Share & notify</button><p id="publish-status" class="meta" role="status"></p></form></section>`;
 const form=$('#teacher-publish');form.elements.audience.onchange=()=>{$('#audience-groups').hidden=form.elements.audience.value!=='groups';$('#audience-members').hidden=form.elements.audience.value!=='members'};
 form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(form),data=Object.fromEntries(fd);data.groups=fd.getAll('groups');data.members=fd.getAll('members');try{const r=await api('broadcast_publish',data);toast('Shared with '+r.recipients+' members');$('#publish-status').innerHTML=`Shared successfully. <a href="#resources?post=${r.id}">Open shared resource</a>`;form.reset();$('#audience-groups').hidden=$('#audience-members').hidden=true}catch(e){toast(e.message,'error')}};
}

async function resourcesPage(seq,params={}){
 if(params.post){const d=await get('broadcast_get',{id:params.post});if(seq!==routeSeq)return;const b=d.post,x=d.item,dl='download.php?broadcast='+Number(b.id);$('#main').innerHTML=heading(b.title,'Shared by '+b.author)+`<article class="card"><p style="white-space:pre-wrap">${esc(b.message)}</p>${x?`<h2 class="mt-5">${esc(x.title)}</h2>${x.kind==='file'?galleryMedia(x,dl+'&inline=1',true):`<pre class="drop-snippet mt-4">${esc(x.content)}</pre>`}<a class="btn primary mt-4" href="${dl}">${icon('download')}Download resource</a>`:'<p class="meta mt-4">Announcement only, or the publisher removed the attached resource.</p>'}<div class="row mt-5"><a class="btn" href="#resources">All shared resources</a><button class="btn" id="resource-link">Copy link</button>${Number(b.author_id)===Number(me.id)||['admin','super_admin'].includes(me.role)?'<button class="btn danger" id="resource-revoke">Revoke share</button>':''}</div></article>`;$('#resource-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('Link copied')}catch(e){toast('Copy the URL from your address bar','info')}};if($('#resource-revoke'))$('#resource-revoke').onclick=()=>modal('Revoke shared resource?',`<p>Recipients will lose access to this share. Your original resource stays in your workspace.</p><button class="btn danger mt-4" data-confirm>Revoke</button>`,dlg=>dlg.querySelector('[data-confirm]').onclick=async()=>{try{await api('broadcast_revoke',{id:b.id});dlg.close();go('resources')}catch(e){toast(e.message,'error')}});return;}
 const page=Number(params.page)||1,d=await get('broadcast_list',{page});if(seq!==routeSeq)return;
 $('#main').innerHTML=heading('Shared Resources','Teacher resources and announcements shared with you.')+`<div class="grid2">${d.posts.map(p=>`<article class="card"><span class="badge">${esc(p.audience==='all'?'All members':'Selected audience')}</span><h2 class="mt-3">${esc(p.title)}</h2><p class="meta mt-2">${esc(p.author)} · ${date(p.created_at)}</p><p class="mt-3">${esc(p.message.slice(0,180))}</p>${p.resource_title?`<p class="meta mt-3">${esc(p.resource_kind)} · ${esc(p.resource_title)}</p>`:''}<a class="btn small primary mt-4" href="#resources?post=${p.id}">Open resource</a></article>`).join('')||empty('No shared updates yet','Your teacher’s shared resources will appear here.')}</div><div class="row mt-5">${page>1?`<a class="btn" href="#resources?page=${page-1}">Previous</a>`:''}${d.has_more?`<a class="btn" href="#resources?page=${page+1}">Next</a>`:''}</div>`;
}

function authPage(mode,params={}){const register=mode==='register', forgot=mode==='forgot',reset=mode==='reset',verify=mode==='verify';app.innerHTML=`<div class="auth"><div class="auth-story">${brand()}<h1>Your next great idea<br>belongs here.</h1><p>One private workspace for your lab programs, lecture notes and everything you learn along the way.</p><div class="card"><div class="row">${icon('lock')}<b>Private by default</b></div><p class="text-sm mt-3">Save code. Keep your study materials close. Find your work from any device.</p></div></div><div class="auth-panel"><div class="auth-form"><h2>${register?'Create your workspace':forgot?'Forgot password?':reset?'Set a new password':verify?'Verify your email':'Welcome back'}</h2><p class="muted mt-2">${register?'A little space for everything you learn.':forgot?'We’ll send a reset link to your account email.':reset?'Use at least 12 characters.':verify?'Confirm your address to keep your workspace secure.':'Sign in to continue where you left off.'}</p><form id="auth-form">${register?'<label class="field">Full name<input class="input" name="name" required maxlength="120" autocomplete="name"></label><label class="field">Username<input class="input" name="username" required minlength="3" maxlength="24" pattern="[a-zA-Z][a-zA-Z0-9_]{2,23}" autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false"><small>3–24 letters, numbers or underscores; start with a letter.</small></label><label class="field">Account type<select class="input" name="role"><option value="student">Student</option><option value="teacher">Teacher</option></select><small>New accounts need email verification and administrator approval.</small></label>':''}${!reset&&!verify?(register||forgot?'<label class="field">Email address<input class="input" name="email" type="email" required maxlength="190" autocomplete="email" inputmode="email"></label>':'<label class="field">Username or email<input class="input" name="identifier" type="text" required maxlength="190" autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" enterkeyhint="next"></label><p class="meta">You can find or change your username in Settings.</p>'):''}${!forgot&&!verify?`<label class="field">${reset?'New password':'Password'}<input class="input" name="password" type="password" required ${register||reset?'minlength="12" maxlength="72" autocomplete="new-password"':'autocomplete="current-password"'}>${register?'<small>12–72 characters. Use a unique password.</small>':''}</label>`:''}${!register&&!forgot&&!reset&&!verify?'<div class="row between"><label class="check"><input type="checkbox" name="remember">Remember me on this device</label><a href="#forgot" class="text-sm">Forgot password?</a></div>':''}<div class="error hidden" id="auth-error"></div><div class="success hidden" id="auth-success"></div><button class="btn primary" id="auth-submit">${register?'Create account':forgot?'Send reset link':reset?'Change password':verify?'Verify email':'Sign in'}</button></form><p class="foot"><a class="btn soft" href="#drop">${icon('share')}Anonymous share — no login needed</a></p><p class="foot"><a href="#features">Features & Changelog</a> · <a href="#drop">Anonymous share: code, files & QR →</a></p><p class="foot">${register?'Already have an account? <a href="#login">Sign in</a>':!forgot&&!reset&&!verify?'New here? <a href="#register">Create an account</a>':'<a href="#login">Back to sign in</a>'}</p>${window.BOU.local?'<div class="notice mt-5">Local test mode: outgoing emails are saved as text files in storage/mail. Open the newest file to get your verification or reset link.</div>':''}</div></div></div>`;
if(!register&&!forgot&&!reset&&!verify){try{const saved=localStorage.getItem('bou-login-identifier');if(saved)$('#auth-form').elements.identifier.value=saved}catch{}}
$('#auth-form').onsubmit=async e=>{e.preventDefault();let b=$('#auth-submit');b.disabled=true;$('#auth-error').classList.add('hidden');try{let input={...Object.fromEntries(new FormData(e.target)),token:params.token};input.remember=!!input.remember;let r=await api(register?'register':forgot?'forgot':reset?'reset':verify?'verify':'login',input);if(r.user){if(!register){try{if(input.remember)localStorage.setItem('bou-login-identifier',input.identifier);else localStorage.removeItem('bou-login-identifier')}catch{}}me=r.user;go(me.verified_at?'overview':'verification')}else if(verify){toast(r.message);let s=await get('session');me=s.user;go(me?'overview':'login')}else{$('#auth-success').textContent=r.message;$('#auth-success').classList.remove('hidden');if(reset){e.target.querySelector('[name=password]').value='';b.disabled=true}}}catch(e){$('#auth-error').textContent=e.message;$('#auth-error').classList.remove('hidden')}finally{b.disabled=reset&&!$('#auth-success').classList.contains('hidden')}};}
function verificationPage(){app.innerHTML=`<div class="auth">${'<div class="auth-story">'+brand()+'<h1>Almost there.</h1><p>Your personal workspace is one email away.</p></div>'}<div class="auth-panel"><div class="auth-form"><h2>Check your inbox</h2><p class="muted mt-3">We sent a verification link to ${esc(me.email)}. Check your spam folder too.</p><button class="btn primary mt-6" id="resend">Resend verification</button><button class="btn mt-6 ml-2" id="check-verification">I’ve verified</button><button class="btn mt-4" id="signout">Sign out</button>${window.BOU.local?'<div class="notice mt-5">Local mode: open the newest text file in storage/mail and paste its link into your browser.</div>':''}</div></div></div>`;$('#resend').onclick=async()=>{try{let r=await api('resend',{});toast(r.message)}catch(e){toast(e.message,'error')}};$('#check-verification').onclick=async()=>{let s=await get('session');me=s.user;if(me?.verified_at)go('overview');else toast('Your address is not verified yet.')};$('#signout').onclick=logout;}
async function logout(){await api('logout',{});me=null;notificationState={items:[],total:0,unread:0,latest_id:0,revision:'',owner:null,offline:false};notificationCheckedAt=0;clearTimeout(notificationScheduled);currentItem=null;dirty=false;go('login')}
async function settingsPage(seq){if(seq!==routeSeq)return;let p=me.preferences||{};$('#main').innerHTML=heading('Settings','Your profile, account security and workspace preferences.')+`<div class="stack settings-layout"><section class="card"><h2>Profile photo</h2><div class="profile-photo-row mt-4"><span class="profile-photo-preview">${avatarMarkup(me)}</span><form id="photo-form" class="stack"><label class="field">Choose profile photo<input class="input" type="file" name="photo" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" required></label><p class="meta">Your photo is resized on this device before upload. JPG, PNG or WebP recommended.</p>${progressMarkup()}<div class="row"><button class="btn primary">Upload / replace photo</button>${me.photo_url?'<button class="btn" type="button" id="remove-photo">Remove photo</button>':''}</div><p id="photo-status" role="status"></p></form></div></section><section class="card"><h2>Profile & preferences</h2><form id="profile-form" class="stack mt-5"><div class="grid2"><label class="field">Name<input class="input" name="name" value="${esc(me.name)}" required maxlength="120"></label><label class="field">Username<input class="input" name="username" value="${esc(me.username)}" required minlength="3" maxlength="24" pattern="[a-zA-Z][a-zA-Z0-9_]{2,23}" autocapitalize="none" autocorrect="off" spellcheck="false"><small>Use this username or your email to sign in.</small></label><label class="field">Semester<input class="input" name="semester" value="${esc(me.semester)}" placeholder="Semester 5" maxlength="60"></label><label class="field">Avatar initials<input class="input" name="avatar" value="${esc(me.avatar)}" placeholder="RH" maxlength="3"><small>1–3 letters or numbers. Used when no profile photo is set.</small></label><label class="field">Default code language<select name="default_language" class="input">${languages.map(l=>`<option ${l===(p.default_language||'C')?'selected':''}>${esc(l)}</option>`).join('')}</select></label><label class="field">Timezone<select name="timezone" class="input">${['Asia/Dhaka','UTC','Asia/Kolkata','Europe/London','America/New_York'].map(t=>`<option ${(p.timezone||'Asia/Dhaka')===t?'selected':''}>${t}</option>`).join('')}</select></label></div><div><h3 class="mb-3">Email preferences</h3>${[['security_email','Security alerts'],['sharing_email','Content sharing']].map(([k,t])=>`<label class="check"><input type="checkbox" name="${k}" ${p[k]!==false?'checked':''}>${t}</label>`).join('')}<p class="meta mt-2">Verification, recovery and password-change messages are always sent.</p></div><button class="btn primary self-start">Save profile</button></form></section><section class="card"><h2>Change password</h2><form id="password-form" class="stack mt-5"><label class="field">Current password<input class="input" name="current_password" type="password" autocomplete="current-password" required></label><label class="field">New password<input class="input" name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><button class="btn self-start">Change password</button></form></section><section class="card"><h2>Email address</h2><p class="muted mt-2">Current address: ${esc(me.email)}</p><form id="email-form" class="stack mt-5"><label class="field">New email<input type="email" name="email" class="input" required></label><label class="field">Password<input type="password" name="password" class="input" autocomplete="current-password" required></label><button class="btn self-start">Send verification</button></form></section><section class="card"><h2>Sessions & data</h2><p class="muted text-sm mt-2">Sign out all browsers, or export your code, notes and metadata. Download file bytes separately.</p><div class="row flex-wrap mt-5"><a class="btn" href="api.php?action=export">${icon('download')}Export workspace</a><button class="btn" id="logout-all">Sign out all sessions</button><button class="btn" id="signout">Sign out</button></div></section><section class="card"><h2>Account deletion</h2><p class="muted mt-2 text-sm">Request deletion from an administrator. You will be contacted before it is processed.</p><form class="row mt-4" id="delete-form"><input class="input" type="password" name="password" placeholder="Confirm password" autocomplete="current-password" required><button class="btn danger">Request deletion</button></form></section></div>`;
bindPhotoForm();$('#profile-form').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));for(let k of ['security_email','sharing_email'])data[k]=!!data[k];try{let r=await api('settings',data);me=r.user;toast('Profile saved');render()}catch(e){toast(e.message,'error')}};for(let [id,a] of [['password-form','password'],['email-form','email'],['delete-form','delete_request']])$('#'+id).onsubmit=async e=>{e.preventDefault();try{let r=await api(a,Object.fromEntries(new FormData(e.target)));toast(r.message||'Request completed');e.target.reset()}catch(e){toast(e.message,'error')}};$('#signout').onclick=logout;$('#logout-all').onclick=async()=>{try{await api('logout_all',{});;me=null;dirty=false;go('login')}catch(e){toast(e.message,'error')}};}
function notificationKind(x){return /shared/i.test(x.title)?'shares':/storage/i.test(x.title)?'storage':/sign-in|password|security|deletion/i.test(x.title)?'security':'academics'}
function notificationCenter(xs,compact=false){const unread=notificationState.unread,total=notificationState.total;return `<section class="notification-center ${compact?'compact-notifications':''}"><header><h2 aria-label="Notification center">Notifications <span class="notification-count">${total}</span></h2><button class="micro-link" data-mark-read ${unread?'':'disabled'}>Mark all as read</button></header><div class="notification-tabs">${[['all','All ('+total+')'],['unread','Unread ('+unread+')'],['academics','Academics'],['shares','Code Shares'],['security','Security']].map(([k,t])=>`<button data-notification-filter="${k}" class="${k==='all'?'selected':''}">${t}</button>`).join('')}</div><div class="notification-list">${xs.length?xs.map(x=>{const k=notificationKind(x),symbol={shares:'share',storage:'upload',security:'lock',academics:'bell'}[k];return `<article class="notification-row ${x.read_at?'':'unread'}" data-category="${k}" data-unread="${!x.read_at}" data-notification-id="${x.id}"><span class="notification-dot"></span><span class="micro-symbol ${k}">${icon(symbol)}</span><div class="notification-copy"><div class="notification-title"><h3>${esc(x.title)}</h3><time>${date(x.created_at)}</time></div><p>${esc(compact?(x.content.length>110?x.content.slice(0,107)+'…':x.content):x.content)}</p>${!x.read_at?`<button type="button" class="iconbtn notification-read" data-read-one="${x.id}" aria-label="Mark as read" title="Mark as read">${icon('check')}</button>`:''}<button type="button" class="iconbtn notification-delete" data-delete-notification="${x.id}" aria-label="Delete notification" title="Delete notification">${icon('trash')}</button>${k==='shares'?'<a href="#shared-with-me" class="btn soft small">View shared content →</a>':''}</div></article>`}).join(''):''}<div class="notification-empty" ${xs.length?'hidden':''}>${icon('bell')}<strong>You’re all caught up</strong><p>No notifications in this view.</p></div></div><div class="notification-sync" role="status">${notificationState.offline?(navigator.onLine?'Updates unavailable · retrying automatically':'Offline · updates paused'):'Live updates · checks every 3 seconds'}${total>xs.length?' · Latest 100 shown':''}</div>${compact?'<a class="notification-footer" href="#notifications">View Notification History →</a>':''}</section>`}
let notificationState={items:[],total:0,unread:0,latest_id:0,revision:'',owner:null,offline:false},notificationRequest=null,notificationMutating=false,notificationCheckedAt=0,notificationScheduled=null;
function notificationBadge(){const n=notificationState.unread;for(const el of document.querySelectorAll('#header-notifications,.reference-sidebar a[href="#notifications"]')){el.querySelectorAll('.absolute,.w-1\\.5,.bg-brand-red').forEach(x=>x.remove());let badge=el.querySelector('.unread-number');if(!badge){badge=document.createElement('span');badge.className='unread-number';el.append(badge)}badge.textContent=n>99?'99+':String(n);badge.hidden=!n;el.setAttribute('aria-label',`Notifications, ${n} unread`)} }
function paintNotifications(root){if(!root?.isConnected)return;const filter=root.querySelector('.notification-tabs .selected')?.dataset.notificationFilter||'all',scroll=root.querySelector('.notification-list')?.scrollTop||0;root.innerHTML=notificationCenter(notificationState.items,root.id==='micro-flyout');bindNotifications(root,notificationState.items);root.querySelector(`[data-notification-filter="${filter}"]`)?.click();root.querySelector('.notification-list').scrollTop=scroll;}
async function syncNotifications(force=false){if(!me?.verified_at||(me.approval||'approved')!=='approved'||notificationMutating)return;if(!force&&Date.now()-notificationCheckedAt<2800)return;if(notificationRequest)return notificationRequest;const owner=me.id;if(notificationState.owner!==owner)notificationState={items:[],total:0,unread:0,latest_id:0,revision:'',owner,offline:false};notificationRequest=(async()=>{try{const d=await sessionClient.get('notification_state',{since:force?'':notificationState.revision},{signal:AbortSignal.timeout(8000)});if(me?.id!==owner)return;const previous=notificationState.latest_id,initial=!!notificationState.revision,changed=d.revision!==notificationState.revision||notificationState.offline;notificationCheckedAt=Date.now();notificationState={...notificationState,...d,items:d.items||notificationState.items,owner,offline:false};notificationBadge();if(changed){for(const root of document.querySelectorAll('.notifications-page,#micro-flyout'))if(root.querySelector('.notification-center'))paintNotifications(root);if(initial&&d.latest_id>previous){const fresh=notificationState.items.filter(x=>x.id>previous&&!x.read_at);if(fresh.length)toast(fresh.length===1?fresh[0].title:`${fresh.length} new notifications`,'info')}}}catch(e){notificationState.offline=true;document.querySelectorAll('.notification-sync').forEach(x=>x.textContent=navigator.onLine?'Updates unavailable · retrying automatically':'Offline · updates paused');if(force)throw e}finally{notificationRequest=null}})();return notificationRequest;}
async function readNotifications(data,action='mark_read'){if(notificationMutating)return;notificationMutating=true;const roots=[...document.querySelectorAll('.notification-center')];roots.forEach(x=>x.querySelectorAll('[data-mark-read],[data-read-one],[data-delete-notification]').forEach(b=>b.disabled=true));try{if(notificationRequest)await notificationRequest;await api(action,data)}catch(e){toast(e.message,'error')}finally{notificationMutating=false;await syncNotifications(true).catch(()=>{});roots.forEach(x=>{const root=x.parentElement;if(root?.isConnected)paintNotifications(root)})}}
function bindNotifications(root,xs){root.querySelectorAll('[data-notification-filter]').forEach(b=>b.onclick=()=>{root.querySelectorAll('[data-notification-filter]').forEach(t=>{t.classList.toggle('selected',t===b);t.setAttribute('aria-pressed',String(t===b))});let visible=0;root.querySelectorAll('.notification-row').forEach(r=>{r.hidden=!(b.dataset.notificationFilter==='all'||b.dataset.notificationFilter==='unread'&&r.dataset.unread==='true'||r.dataset.category===b.dataset.notificationFilter);if(!r.hidden)visible++});root.querySelector('.notification-empty').hidden=visible>0});root.querySelector('[data-mark-read]').onclick=()=>readNotifications({up_to:notificationState.latest_id});root.querySelectorAll('[data-read-one]').forEach(b=>b.onclick=()=>readNotifications({id:+b.dataset.readOne}));root.querySelectorAll('[data-delete-notification]').forEach(b=>b.onclick=()=>readNotifications({id:+b.dataset.deleteNotification},'delete_notification'));root.querySelector('.notification-footer')?.addEventListener('click',closeFlyout);root.querySelectorAll('.notification-row a').forEach(a=>a.onclick=closeFlyout);}
