async function helpPage(seq){let d=await get('help');if(seq!==routeSeq)return;$('#main').innerHTML=heading('Help & Feedback','A few useful answers, and a way to reach us.')+`<div class="grid2"><div class="card stack"><h2>Your workspace</h2><div><h3>How do I save code?</h3><p class="muted mt-2 text-sm">Choose New Code, add a title and start writing. After three seconds of inactivity your changes are saved. Check the saved state before closing the page.</p></div><div><h3>Can I run a program?</h3><p class="muted mt-2 text-sm">Execution is disabled. Download your code and run it in your local IDE.</p></div><div><h3>Is my content private?</h3><p class="muted mt-2 text-sm">Yes. Only a share you create gives read-only access. Attachments stay private. You can revoke any share.</p></div><div><h3>Why does Trash use storage?</h3><p class="muted mt-2 text-sm">Trashed files can be restored, so their bytes stay stored. Delete them permanently to free space.</p></div></div><div class="card"><h2>Send feedback or report content</h2><p class="muted mt-2">Contact <a href="mailto:${esc(d.support_email)}">${esc(d.support_email)}</a> or send a message here.</p><form id="feedback-form" class="stack mt-5"><label class="field">Message<textarea class="input" name="content" required maxlength="4000" placeholder="Describe the issue. Include a share link if reporting content."></textarea></label><button class="btn primary">Send to administrator</button></form></div></div>`;$('#feedback-form').onsubmit=async e=>{e.preventDefault();try{await api('report',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('Message sent to the administrator')}catch(e){toast(e.message,'error')}}}
