function avatarMarkup(u){return u?.photo_url?`<img class="member-photo" src="${esc(u.photo_url)}" alt="${esc(u.name||'Profile')}" loading="lazy">`:esc(u?.avatar||u?.name?.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()||'U')}
async function preparedPhoto(file){
 if(!file)throw Error('Choose a profile photo first.');if(file.size>25*1048576)throw Error('Choose a photo smaller than 25 MB.');
 const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const scale=Math.min(1,512/Math.max(image.naturalWidth,image.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob)throw Error('Could not prepare photo.');return new File([blob],'profile.jpg',{type:'image/jpeg'});}catch{throw Error('This photo cannot be decoded here. Choose a JPG, PNG or WebP photo.');}finally{URL.revokeObjectURL(url)}
}
function bindPhotoForm(){const form=$('#photo-form');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const status=$('#photo-status'),buttons=[...form.querySelectorAll('button,input')];buttons.forEach(x=>x.disabled=true);try{status.textContent='Preparing photo…';const file=await preparedPhoto(form.elements.photo.files[0]),fd=new FormData();fd.set('file',file);const r=await sessionClient.upload('profile_photo',fd,(ratio,state)=>updateProgress(form.querySelector('.upload-feedback'),ratio===null?null:ratio*100,state==='processing'?'Saving photo…':'Uploading photo…',file.name));me=r.user;toast('Profile photo updated');await render();}catch(e){status.textContent=e.message;toast(e.message,'error');}finally{buttons.forEach(x=>x.disabled=false)}};$('#remove-photo')?.addEventListener('click',async()=>{try{const r=await api('profile_photo_remove',{});me=r.user;toast('Photo removed');await render()}catch(e){toast(e.message,'error')}});}

