function gamificationRules(){modal('Leaderboard scoring',`<p class="muted">Points reward workspace habits. Completed goals and courses are self-reported; this is not a verified grading or plagiarism-detection system.</p><div class="stack mt-4">${[['Original code entry (20+ characters)','20 XP · max 100/day'],['Original note (40+ characters)','10 XP · max 50/day'],['First share of an item','5 XP · max 25/day'],['Completed lab goal','20 XP · max 60/day'],['Completed course','50 XP · max 100/day'],['Active study day','10 XP/day'],['Daily sprint: code + completed goal','20 bonus XP/day']].map(([t,p])=>`<div class="row between"><span>${t}</span><span class="badge">${p}</span></div>`).join('')}</div><p class="meta mt-4">Editing, duplicate content, repeated sharing and toggling completed work do not earn repeat XP. Awarded XP remains after an item is trashed. Rankings use UTC periods; equal scores share a rank. Levels advance every 250 XP.</p><h3 class="mt-5">Tier milestones</h3><div class="tags mt-3">${['Rising: 0','Bronze: 1,000','Silver: 2,000','Gold: 2,500','Diamond: 2,900','Grandmaster: 4,000'].map(t=>`<span class="tag">${t} XP</span>`).join('')}</div>`)}
